    logs = []
    end = time.time() + interval_s
    while time.time() < end:
        for c in psutil.net_connections(kind='inet'):
            if c.laddr.ip == host and c.status == 'ESTABLISHED':
                logs.append({
                    'timestamp': time.time(),
                    'src_ip': c.raddr.ip if c.raddr else '',
                    'src_port': c.raddr.port if c.raddr else None
                })
        time.sleep(1)
    return logs
