from scapy.all import rdpcap, DNSQR, DNSRR
import re
from collections import Counter

def _entropy(s: str) -> float:
    prob = [float(s.count(c)) / len(s) for c in set(s)]
    return -sum(p * (0 if p == 0 else __import__('math').log2(p)) for p in prob)

def analyze_dns_traffic(pcap_file: str) -> dict:
    pkts = rdpcap(pcap_file)
    domains = []
    for pkt in pkts:
        if pkt.haslayer(DNSQR):
            qname = pkt[DNSQR].qname.decode().rstrip('.')
            domains.append(qname.lower())
        if pkt.haslayer(DNSRR):
            rname = pkt[DNSRR].rrname.decode().rstrip('.')
            domains.append(rname.lower())

    # simple DGA detection: high entropy, length > 12, random-looking
    suspicious = set()
    for d in domains:
        labels = d.split('.')
        for lbl in labels:
            if len(lbl) > 12 and _entropy(lbl) > 3.5:
                suspicious.add(d)
                break

    # tunneling / exfil: many subdomains with similar base
    base_counts = Counter('.'.join(d.split('.')[1:]) for d in domains)
    for base, cnt in base_counts.items():
        if cnt > 20:  # many queries to same base with varying subdomains
            for d in domains:
                if d.endswith('.' + base):
                    suspicious.add(d)

    return {
        "total_queries": len(domains),
        "unique_domains": len(set(domains)),
        "suspicious_domains": sorted(suspicious)
    }
