import re
from pathlib import Path

def harden_ssh_config(config_path: str) -> dict:
    """
    Analyzes an OpenSSH client/server config file and returns a dict of
    recommended hardening changes.
    """
    recommendations = {}
    cfg = Path(config_path).read_text().splitlines()

    # Helper to find last value of a directive (ignores comments)
    def last_value(directive):
        pattern = re.compile(rf'^\s*{directive}\s+(.*)', re.IGNORECASE)
        for line in reversed(cfg):
            if line.lstrip().startswith('#'):
                continue
            m = pattern.match(line)
            if m:
                return m.group(1).strip()
        return None

    # 1. Protocol version
    proto = last_value('Protocol')
    if proto and proto != '2':
        recommendations['Protocol'] = 'Set to 2 (or remove to default to 2)'

    # 2. Disable root login
    permit_root = last_value('PermitRootLogin')
    if permit_root and permit_root.lower() not in ('no', 'prohibit-password'):
        recommendations['PermitRootLogin'] = 'Set to no or prohibit-password'

    # 3. Use strong ciphers, MACs, KexAlgorithms
    weak_ciphers = {'3des-cbc', 'aes128-cbc', 'aes192-cbc', 'aes256-cbc'}
    ciphers = set(last_value('Ciphers').split(',')) if last_value('Ciphers') else set()
    if weak_ciphers & ciphers:
        recommendations['Ciphers'] = 'Remove weak ciphers (e.g., CBC)'

    weak_macs = {'hmac-md5', 'hmac-sha1', 'umac-64@openssh.com'}
    macs = set(last_value('MACs').split(',')) if last_value('MACs') else set()
    if weak_macs & macs:
        recommendations['MACs'] = 'Remove weak MACs (e.g., hmac-md5, hmac-sha1)'

    weak_kex = {'diffie-hellman-group1-sha1', 'diffie-hellman-group14-sha1'}
    kex = set(last_value('KexAlgorithms').split(',')) if last_value('KexAlgorithms') else set()
    if weak_kex & kex:
        recommendations['KexAlgorithms'] = 'Remove weak KEX algorithms'

    # 4. Disable empty passwords
    permit_empty = last_value('PermitEmptyPasswords')
    if permit_empty and permit_empty.lower() != 'no':
        recommendations['PermitEmptyPasswords'] = 'Set to no'

    # 5. Limit authentication attempts
    max_auth = last_value('MaxAuthTries')
    if max_auth and int(max_auth) > 4:
        recommendations['MaxAuthTries'] = 'Set to 4 or lower'

    # 6. Disable X11 forwarding if not needed
    x11 = last_value('X11Forwarding')
    if x11 and x11.lower() != 'no':
        recommendations['X11Forwarding'] = 'Set to no unless required'

    # 7. Enforce strict modes on authorized_keys
    strict_modes = last_value('StrictModes')
    if strict_modes and strict_modes.lower() != 'yes':
        recommendations['StrictModes'] = 'Set to yes'

    return recommendations
